#include <stdio.h>
 void binary32(unsigned int value, char *text);
 void show_groups(const char *text);
 int main(void) {
     char text[33];
     int value = 0;
     while (scanf("%d", &value) == 1) {
         binary32((unsigned int)value, text);
         printf("%d: ", value);
         show_groups(text);
     }
     puts("END");
     return 0;
 }

void binary32(unsigned int value, char *text) {
    for (int position = 31; position >= 0; position--) {
        text[position] = (char)('0' + (value & 1u));
        value >>= 1;
    }
    text[32] = '\0';
}
void show_groups(const char *text) {
    for (int position = 0; position < 32; position++) {
        putchar(text[position]);
        if (position % 4 == 3 && position < 31) putchar(' ');
    }
    putchar('\n');
}

#include <stdio.h>
 void binary32(unsigned int value, char *text);
 void show_groups(const char *text);
 unsigned int flip_low(unsigned int value, int bits);
 int main(void) {
     unsigned int value = 0u;
     char text[33];
     if (scanf("%u", &value) != 1) return 1;
     binary32(value, text);
     printf("before=");
     show_groups(text);
     unsigned int changed = flip_low(value, 4);
     binary32(changed, text);
     printf("after=");
     show_groups(text);
     printf("result=%u\n", changed);
     return 0;
 }
 unsigned int flip_low(unsigned int value, int bits) {
     if (bits < 0 || bits > 32) return value;
     unsigned int mask = 0u;
     unsigned int single = 1u;
     for (int i = 0; i < bits; i++) {
         mask |= single;
         single <<= 1;
     }
     return value ^ mask;
 }

void binary32(unsigned int value, char *text) {
    for (int position = 31; position >= 0; position--) {
        text[position] = (char)('0' + (value & 1u));
        value >>= 1;
    }
    text[32] = '\0';
}
void show_groups(const char *text) {
    for (int position = 0; position < 32; position++) {
        putchar(text[position]);
        if (position % 4 == 3 && position < 31) putchar(' ');
    }
    putchar('\n');
}

#include <stdio.h>
#include <stdbool.h>
enum palette { black, red, green, yellow, blue, purple, cyan, white };
enum line { solid, dotted, dashed };
struct appearance {
    bool opaque : 1;
    unsigned int fill : 3;
    unsigned int : 4;
    bool border : 1;
    unsigned int edge : 3;
    unsigned int style : 2;
    unsigned int : 2;
};
void describe(const struct appearance *item);
int main(void) {
    struct appearance panel = {true, blue, true, yellow, dotted};
    describe(&panel);
    panel.opaque = false;
    panel.fill = cyan;
    panel.edge = red;
    panel.style = solid;
    describe(&panel);
    return 0;
}
void describe(const struct appearance *item) {
    const char *colors[8] = {"black", "red", "green", "yellow", "blue", "purple", "cyan", "white"};
    printf("opaque=%u fill=%s border=%u edge=%s style=",
           (unsigned)item->opaque, colors[item->fill], (unsigned)item->border, colors[item->edge]);
    switch (item->style) {
        case solid: puts("solid"); break;
        case dotted: puts("dotted"); break;
        case dashed: puts("dashed"); break;
        default: puts("unknown"); break;
    }
}

#include <stdio.h>
#include <limits.h>
struct fields {
    unsigned int opaque : 1;
    unsigned int fill : 3;
    unsigned int : 4;
    unsigned int border : 1;
    unsigned int edge : 3;
    unsigned int style : 2;
    unsigned int : 2;
};
union view { struct fields fields; unsigned int word; };
void show_fields(const struct fields *item);
void show_word(unsigned int word);
int main(void) {
    union view panel = {{1, 2, 1, 4, 2}};
    if (CHAR_BIT != 8 || sizeof(unsigned int) != 4 || UINT_MAX != 4294967295u || sizeof panel != 4) {
        puts("THIS READING DEMO REQUIRES A 32-BIT UNSIGNED VIEW");
        return 0;
    }
    show_fields(&panel.fields);
    show_word(panel.word);
    panel.word = (panel.word & ~0x0eu) | (6u << 1);
    panel.word ^= 1u;
    panel.word = (panel.word & ~0x0e00u) | (1u << 9);
    panel.word = (panel.word & ~0x3000u) | (1u << 12);
    show_word(panel.word);
    show_fields(&panel.fields);
    return 0;
}
void show_fields(const struct fields *item) {
    printf("fields: %u %u %u %u %u\n", (unsigned)item->opaque, (unsigned)item->fill,
           (unsigned)item->border, (unsigned)item->edge, (unsigned)item->style);
}
void show_word(unsigned int word) {
    printf("word: %08x | assumed slots: %u %u %u %u %u\n", word,
           word & 1u, (word >> 1) & 7u, (word >> 8) & 1u,
           (word >> 9) & 7u, (word >> 12) & 3u);
}

#include <stdio.h>
#include <stdalign.h>
int main(void) {
    double first = 1.0, second = 2.0;
    char ordinary = 'a';
    alignas(double) char aligned = 'b';
    printf("char alignment=%zu\n", alignof(char));
    printf("double alignment=%zu\n", alignof(double));
    printf("first=%p ordinary=%p second=%p aligned=%p\n",
           (void *)&first, (void *)&ordinary, (void *)&second, (void *)&aligned);
    return 0;
}

